data class WordForm(
    val word: String,
    val partOfSpeech: String,
    val meaning: String,
    val example: String,
)

data class RelatedWord(
    val word: String,
    val explanation: String,
    val example: String = "",
)

data class VocabularyProfile(
    val partOfSpeech: String,
    val detailedMeaning: String,
    val forms: List<WordForm>,
    val synonyms: List<RelatedWord>,
    val antonyms: List<RelatedWord>,
    val verbConjugations: VerbConjugations? = null,
)

data class VerbConjugations(
    val base: String,
    val thirdPersonSingular: String,
    val presentParticiple: String,
    val simplePast: String,
    val pastParticiple: String,
)

