    fun forWord(word: VocabularyWord): VocabularyProfile =
        profiles[word.word.uppercase()] ?: VocabularyProfile(
            partOfSpeech = "Word",
            detailedMeaning = word.meaning,
            forms = emptyList(),
            synonyms = emptyList(),
            antonyms = emptyList(),
        )

    private fun profile(
        partOfSpeech: String,
        detailedMeaning: String,
        form: WordForm,
        synonym: RelatedWord,
        antonym: RelatedWord,
        additionalForms: List<WordForm> = emptyList(),
        verbConjugations: VerbConjugations? = null,
    ) = VocabularyProfile(
        partOfSpeech,
        detailedMeaning,
        (listOf(form) + additionalForms).distinctBy { it.partOfSpeech to it.word },
        listOf(synonym),
        listOf(antonym),
        verbConjugations,
    )

    private fun form(word: String, partOfSpeech: String, meaning: String, example: String) =
        WordForm(word, partOfSpeech, meaning, example)

    private fun related(word: String, explanation: String) = RelatedWord(word, explanation)

    private fun conjugations(
        base: String,
        thirdPersonSingular: String,
        presentParticiple: String,
        simplePast: String,
        pastParticiple: String,
    ) = VerbConjugations(base, thirdPersonSingular, presentParticiple, simplePast, pastParticiple)
}
